fn test_prime(candidate: u64) -> bool {
    // Numbers less than 2 are not prime, but the problem states input > 1
    if candidate <= 1 {
        return false;
    }
    
    // Check for small primes
    if candidate <= 3 {
        return true;
    }
    
    // Eliminate even numbers and multiples of 3
    if candidate % 2 == 0 || candidate % 3 == 0 {
        return false;
    }
    
    // Check divisibility by numbers of the form 6k ± 1
    // Only need to check up to sqrt(candidate)
    let limit = (candidate as f64).sqrt() as u64;
    
    let mut i = 5;
    while i <= limit {
        if candidate % i == 0 || candidate % (i + 2) == 0 {
            return false;
        }
        i += 6;
    }
    
    true
}

